package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
)

func firstLine(name string) (string, error) {
	file, err := os.Open(name)
	if err != nil {
		return "", err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	if scanner.Scan() {
		return scanner.Text(), nil
	}
	return "", scanner.Err()
}

func main() {
	dir, err := os.MkdirTemp("", "close-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	name := filepath.Join(dir, "message.txt")
	if err := os.WriteFile(name, []byte("first\nsecond\n"), 0o600); err != nil {
		panic(err)
	}
	line, err := firstLine(name)
	if err != nil {
		panic(err)
	}
	fmt.Println(line)
}
