package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
)

func fileSize(name string) (int, error) {
	file, err := os.Open(name)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	data, err := io.ReadAll(file)
	return len(data), err
}

func main() {
	dir, err := os.MkdirTemp("", "loop-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	names := []string{}
	for i, text := range []string{"a", "bb", "ccc"} {
		name := filepath.Join(dir, fmt.Sprintf("%d.txt", i))
		if err := os.WriteFile(name, []byte(text), 0o600); err != nil {
			panic(err)
		}
		names = append(names, name)
	}
	for _, name := range names {
		size, err := fileSize(name)
		if err != nil {
			panic(err)
		}
		fmt.Println(size)
	}
}
