package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

func writeReport(name string) (err error) {
	file, err := os.Create(name)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, file.Close()) }()

	writer := bufio.NewWriter(file)
	if _, err = writer.WriteString("status=ready\n"); err != nil {
		return err
	}
	if err = writer.Flush(); err != nil {
		return err
	}
	return file.Sync()
}

func main() {
	dir, err := os.MkdirTemp("", "write-demo")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	name := filepath.Join(dir, "report.txt")
	if err := writeReport(name); err != nil {
		panic(err)
	}
	data, err := os.ReadFile(name)
	if err != nil {
		panic(err)
	}
	fmt.Print(string(data))
}
